package com.agent.web.mcp.runtime;
import com.agent.core.tool.mcp.McpStdioProcess; import java.io.*; import java.util.concurrent.atomic.AtomicBoolean;
public final class DockerMcpStdioProcess implements McpStdioProcess { private final InputStream out; private final OutputStream in; private final InputStream err; private final Runnable destroy; private final AtomicBoolean alive=new AtomicBoolean(true); DockerMcpStdioProcess(InputStream out,OutputStream in,InputStream err,Runnable destroy){this.out=out;this.in=in;this.err=err;this.destroy=destroy;} public InputStream stdout(){return out;} public OutputStream stdin(){return in;} public InputStream stderr(){return err;} public boolean isAlive(){return alive.get();} public void destroy(){if(alive.compareAndSet(true,false)){close(in);close(out);close(err);destroy.run();}} private static void close(AutoCloseable c){try{c.close();}catch(Exception ignored){}} }
